import { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { BrowserRouter, Link, NavLink, Navigate, Outlet, Route, Routes, useLocation, useNavigate } from 'react-router-dom';
import {
  Activity, ArrowDown, ArrowRight, ArrowUpRight, Ban, Bell, CalendarDays, Check, CheckCircle2, ChevronLeft,
  ChevronRight, CircleCheckBig, CircleDot, Clock3, ClipboardList, Download, FileText, HeartPulse,
  LayoutDashboard, LogOut, Mail, MapPin, Menu, MessageCircle, Package, Pencil, Phone, Search, Plus,
  Settings, ShieldCheck, SlidersHorizontal, Stethoscope, Timer, TrendingUp, UserPlus, UserRound,
  Users, WalletCards, X,
} from 'lucide-react';
import { appointments as seedAppointments, doctors as seedDoctors, patients as seedPatients, pharmacy as seedPharmacy, queues as seedQueues, weeklyAppointments } from './data/hospitalData';
import type { Appointment, AppointmentStatus, Doctor, DoctorQueue, Patient, PharmacyItem, QueueStatus } from './data/hospitalData';
import './App.css';

type NewAppointment = Pick<Appointment, 'doctorId' | 'doctorName' | 'date' | 'time' | 'phone' | 'reason'> & { patientId?: string; patientName: string };
type HospitalContextValue = {
  patients: Patient[]; appointments: Appointment[]; doctors: Doctor[]; queues: DoctorQueue[]; pharmacy: PharmacyItem[]; currentInsideCount: number; isAuthenticated: boolean;
  addAppointment: (input: NewAppointment) => string; updateAppointmentStatus: (id: string, status: AppointmentStatus) => void; addPatient: (patient: Omit<Patient, 'id' | 'lastVisit' | 'visits'>) => void; updatePatientNotes: (patientId: string, visitId: string, notes: string) => void; toggleDoctor: (id: string) => void; callNext: (doctorId: string) => void; setQueueStatus: (doctorId: string, token: number, status: QueueStatus) => void; login: (username: string, password: string) => boolean; logout: () => void; resetDemo: () => void;
};
const HospitalContext = createContext<HospitalContextValue | undefined>(undefined);

function readStored<T>(key: string, fallback: T): T { try { const value = localStorage.getItem(key); return value ? (JSON.parse(value) as T) : fallback; } catch { return fallback; } }

function HospitalProvider({ children }: { children: ReactNode }) {
  const [patients, setPatients] = useState<Patient[]>(() => readStored('aruna-patients', seedPatients));
  const [appointments, setAppointments] = useState<Appointment[]>(() => readStored('aruna-appointments', seedAppointments));
  const [doctors, setDoctors] = useState<Doctor[]>(() => readStored('aruna-doctors', seedDoctors));
  const [queues, setQueues] = useState<DoctorQueue[]>(() => readStored('aruna-queues', seedQueues));
  const [pharmacy] = useState<PharmacyItem[]>(seedPharmacy);
  const [isAuthenticated, setIsAuthenticated] = useState(() => readStored('aruna-auth', false));
  useEffect(() => { localStorage.setItem('aruna-patients', JSON.stringify(patients)); }, [patients]);
  useEffect(() => { localStorage.setItem('aruna-appointments', JSON.stringify(appointments)); }, [appointments]);
  useEffect(() => { localStorage.setItem('aruna-doctors', JSON.stringify(doctors)); }, [doctors]);
  useEffect(() => { localStorage.setItem('aruna-queues', JSON.stringify(queues)); }, [queues]);
  useEffect(() => { localStorage.setItem('aruna-auth', JSON.stringify(isAuthenticated)); }, [isAuthenticated]);
  const currentInsideCount = useMemo(() => queues.flatMap((queue) => queue.patients).filter((patient) => patient.status === 'inside').length + 9, [queues]);
  const addAppointment = (input: NewAppointment) => { const id = `APT-260819-${String(appointments.length + 1).padStart(2, '0')}`; const nextToken = Math.max(1, ...queues.find((queue) => queue.doctorId === input.doctorId)?.patients.map((patient) => patient.token) ?? [0]) + 1; const appointment: Appointment = { ...input, id, patientId: input.patientId ?? `ARU-${25000 + appointments.length}`, token: nextToken, status: 'Scheduled' }; setAppointments((current) => [appointment, ...current]); return id; };
  const updateAppointmentStatus = (id: string, status: AppointmentStatus) => setAppointments((current) => current.map((appointment) => appointment.id === id ? { ...appointment, status } : appointment));
  const addPatient = (patient: Omit<Patient, 'id' | 'lastVisit' | 'visits'>) => { const id = `ARU-${25000 + patients.length}`; setPatients((current) => [{ ...patient, id, lastVisit: 'New', visits: [] }, ...current]); };
  const updatePatientNotes = (patientId: string, visitId: string, notes: string) => setPatients((current) => current.map((patient) => patient.id === patientId ? { ...patient, visits: patient.visits.map((visit) => visit.id === visitId ? { ...visit, notes } : visit) } : patient));
  const toggleDoctor = (id: string) => setDoctors((current) => current.map((doctor) => doctor.id === id ? { ...doctor, available: !doctor.available } : doctor));
  const callNext = (doctorId: string) => setQueues((current) => current.map((queue) => { if (queue.doctorId !== doctorId) return queue; const next = queue.patients.find((patient) => patient.status === 'waiting'); if (!next) return queue; return { ...queue, currentToken: next.token, patients: queue.patients.map((patient) => patient.status === 'inside' ? { ...patient, status: 'completed', wait: 'Completed' } : patient.token === next.token ? { ...patient, status: 'inside', wait: 'Now' } : patient) }; }));
  const setQueueStatus = (doctorId: string, token: number, status: QueueStatus) => setQueues((current) => current.map((queue) => queue.doctorId === doctorId ? { ...queue, patients: queue.patients.map((patient) => patient.token === token ? { ...patient, status, wait: status === 'inside' ? 'Now' : status === 'completed' ? 'Completed' : patient.wait } : patient) } : queue));
  const login = (username: string, password: string) => { const valid = username.trim().toLowerCase() === 'admin' && password === 'aruna2026'; if (valid) setIsAuthenticated(true); return valid; };
  const logout = () => setIsAuthenticated(false);
  const resetDemo = () => { setPatients(seedPatients); setAppointments(seedAppointments); setDoctors(seedDoctors); setQueues(seedQueues); setIsAuthenticated(false); };
  return <HospitalContext.Provider value={{ patients, appointments, doctors, queues, pharmacy, currentInsideCount, isAuthenticated, addAppointment, updateAppointmentStatus, addPatient, updatePatientNotes, toggleDoctor, callNext, setQueueStatus, login, logout, resetDemo }}>{children}</HospitalContext.Provider>;
}
function useHospital() { const context = useContext(HospitalContext); if (!context) throw new Error('useHospital must be used inside HospitalProvider'); return context; }
function useReveal(path = '') { const location = useLocation(); useEffect(() => { const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add('in-view'); observer.unobserve(entry.target); } }), { threshold: 0.12 }); document.querySelectorAll('.reveal').forEach((node) => observer.observe(node)); return () => observer.disconnect(); }, [location.pathname, path]); }
function useScrollAtmosphere() { useEffect(() => { let frame = 0; const update = () => { frame = 0; const max = Math.max(document.documentElement.scrollHeight - window.innerHeight, 1); document.documentElement.style.setProperty('--aruna-scroll-progress', String(Math.min(window.scrollY / max, 1))); }; const onScroll = () => { if (!frame) frame = requestAnimationFrame(update); }; update(); window.addEventListener('scroll', onScroll, { passive: true }); window.addEventListener('resize', onScroll); return () => { window.removeEventListener('scroll', onScroll); window.removeEventListener('resize', onScroll); if (frame) cancelAnimationFrame(frame); document.documentElement.style.removeProperty('--aruna-scroll-progress'); }; }, []); }

function AnimatedNumber({ value, suffix = '' }: { value: number; suffix?: string }) { const [display, setDisplay] = useState(0); const ref = useRef<HTMLSpanElement>(null); useEffect(() => { const node = ref.current; if (!node) return undefined; let frame = 0; const observer = new IntersectionObserver(([entry]) => { if (!entry.isIntersecting) return; const start = performance.now(); const tick = (now: number) => { const progress = Math.min((now - start) / 900, 1); setDisplay(Math.round(value * (1 - Math.pow(1 - progress, 3)))); if (progress < 1) frame = requestAnimationFrame(tick); }; frame = requestAnimationFrame(tick); observer.disconnect(); }, { threshold: 0.6 }); observer.observe(node); return () => { observer.disconnect(); cancelAnimationFrame(frame); }; }, [value]); return <span ref={ref}>{display.toLocaleString()}{suffix}</span>; }
function ArunaMark({ size = 22 }: { size?: number }) { return <svg width={size} height={size} viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M5 16C5 9.9 9.9 5 16 5s11 4.9 11 11-4.9 11-11 11S5 22.1 5 16Z" stroke="currentColor" strokeWidth="2.4" /><path d="M8.5 16h4l2.1-4.3 3.1 8.6 2.1-4.3h3.7" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" /></svg>; }
function BrandMark({ compact = false }: { compact?: boolean }) { return <Link to="/" className={`brand-mark ${compact ? 'brand-mark-compact' : ''}`} aria-label="Aruna Healthcare home"><span className="brand-mark-icon"><ArunaMark size={compact ? 18 : 21} /></span>{!compact && <span><strong>Aruna</strong><small>Healthcare</small></span>}</Link>; }
function StatusBadge({ status }: { status: string }) { const normalized = status.toLowerCase().replace(/[^a-z]/g, ''); return <span className={`status-badge status-${normalized}`}><CircleDot size={10} />{status}</span>; }
function SectionHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy?: string; action?: ReactNode }) { return <div className="section-heading reveal"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2>{copy && <p>{copy}</p>}</div>{action}</div>; }

function PublicHeader() { const [scrolled, setScrolled] = useState(false); const [open, setOpen] = useState(false); const { currentInsideCount } = useHospital(); useEffect(() => { const handler = () => setScrolled(window.scrollY > 80); window.addEventListener('scroll', handler, { passive: true }); return () => window.removeEventListener('scroll', handler); }, []); const close = () => setOpen(false); return <><div className="public-utility"><div className="wrap"><span>Aruna Healthcare · Vamanjoor, Mangaluru</span><div><a href="tel:+918242222202"><Phone size={13} /> +91 824 222 2202</a><a href="#booking">Patient services <ArrowUpRight size={13} /></a></div></div></div><header className={`public-header ${scrolled ? 'scrolled' : ''}`}><div className="public-nav wrap"><BrandMark /><nav className={open ? 'mobile-open' : ''} aria-label="Main navigation"><a href="#home" onClick={close}>Home</a><a href="#services" onClick={close}>Find care</a><a href="#doctors" onClick={close}>Our doctors</a><a href="#booking" onClick={close}>Appointments</a><a href="#about" onClick={close}>Visit Aruna</a></nav><div className="nav-actions"><span className="live-chip"><CircleDot size={12} /> {currentInsideCount} in care today</span><a className="button button-primary button-small" href="#booking">Book appointment <ArrowRight size={15} /></a><button className="icon-button menu-button" onClick={() => setOpen(!open)} aria-label="Toggle navigation" aria-expanded={open}>{open ? <X size={20} /> : <Menu size={20} />}</button></div></div></header></>; }

function HeroBookingWidget() { return <aside className="booking-widget" aria-label="Appointment information"><div className="widget-topline"><span className="eyebrow">Appointments</span><span className="widget-status"><span /> Open today</span></div><h3>Care starts with one clear next step.</h3><p>Choose a specialist and a time in the secure appointment form below.</p><a className="button button-primary button-full" href="#booking">Find an appointment <ArrowRight size={16} /></a><div className="widget-foot"><ShieldCheck size={14} /> Private records. Confirmed by our team.</div></aside>; }

export function LegacyPublicSite() { useReveal('public'); const { doctors, currentInsideCount, pharmacy } = useHospital(); const availableMedicines = pharmacy.filter((item) => item.stock > 0).length; return <div className="public-site"><PublicHeader /><main><section id="home" className="hero-section"><div className="hero-pattern" /><div className="wrap hero-grid"><div className="hero-copy hero-load"><span className="eyebrow"><span className="eyebrow-dot" /> Mangaluru's trusted clinic</span><h1>Your health,<br /><span>our priority.</span></h1><p>Compassionate care at Vamanjoor, Mangaluru. Book an appointment with our specialist doctors in minutes.</p><div className="hero-actions"><a className="button button-primary" href="#booking">Book appointment <ArrowRight size={17} /></a><a className="button button-quiet" href="#doctors">Meet our doctors <ArrowUpRight size={16} /></a></div><div className="trust-row"><span><Check size={14} /> Verified clinic</span><span><Check size={14} /> Expert doctors</span><span><Check size={14} /> Open 6 days</span></div></div><div className="hero-visual"><div className="clinic-orbit orbit-one" /><div className="clinic-orbit orbit-two" /><div className="hero-note hero-note-top"><Activity size={16} /><span><strong>Care in motion</strong><small>Live clinic operations</small></span></div><div className="hero-console"><div className="console-top"><span>ARUNA / TODAY</span><span className="console-live"><CircleDot size={10} /> Live</span></div><div className="console-main"><div><span className="console-label">Patients inside</span><strong>{currentInsideCount}</strong><small><TrendingUp size={13} /> 12% vs last week</small></div><div className="console-cross"><HeartPulse size={45} /></div></div><div className="console-queue"><span><span className="queue-dot" /> Now serving</span><strong>Token 05</strong><small>Dr. Kavya Shetty</small></div><div className="console-foot"><span>Next available</span><strong>{doctors.find((doctor) => doctor.available)?.name}</strong></div></div><div className="hero-note hero-note-bottom"><Clock3 size={16} /><span><strong>12 min</strong><small>Average wait today</small></span></div><HeroBookingWidget /></div></div></section><section className="stats-strip reveal"><div className="wrap stats-grid"><div><Users size={20} /><span><strong><AnimatedNumber value={currentInsideCount + 12} /></strong><small>Patients today</small></span></div><div><Timer size={20} /><span><strong><AnimatedNumber value={12} suffix=" min" /></strong><small>Average wait</small></span></div><div><CheckCircle2 size={20} /><span><strong><AnimatedNumber value={18} /></strong><small>Consultations done</small></span></div><div><Stethoscope size={20} /><span><strong><AnimatedNumber value={doctors.filter((doctor) => doctor.available).length} /></strong><small>Doctors available</small></span></div></div></section><section id="services" className="section section-soft"><div className="wrap"><SectionHeading eyebrow="Care, under one roof" title="What we treat" copy="Thoughtful everyday care, specialist consultations and a pharmacy team that keeps the details moving." action={<a className="text-link" href="#booking">Talk to our team <ArrowRight size={15} /></a>} /><div className="service-grid reveal stagger-grid">{[['General Medicine', 'Everyday health and preventive care', HeartPulse], ['Pediatrics', 'Gentle care for growing families', Users], ["Women's Health", 'Private, respectful specialist care', Activity], ['Orthopedics', 'Move better with expert guidance', Stethoscope], ['Cardiology', 'Heart health and risk reviews', HeartPulse], ['Dermatology', 'Clear, confident skin health', Activity], ['ENT', 'Head, neck and hearing care', Stethoscope], ['Dental', 'Comfortable, complete dental care', CheckCircle2]].map(([name, description, Icon]) => <div className="service-card" key={String(name)}><span className="service-icon"><Icon size={21} /></span><h3>{name}</h3><p>{description}</p><ArrowUpRight className="service-arrow" size={16} /></div>)}</div></div></section><section id="doctors" className="section"><div className="wrap"><SectionHeading eyebrow="Meet the team" title="Doctors who listen first." copy="A small, experienced team with time for the questions that matter." /><div className="doctor-grid reveal stagger-grid">{doctors.map((doctor) => <div className="doctor-card" key={doctor.id}><div className={`doctor-avatar avatar-${doctor.tint}`}>{doctor.initials}</div><div className="doctor-meta"><span className={doctor.available ? 'availability available' : 'availability'}><CircleDot size={11} /> {doctor.available ? 'Available today' : 'Next: Thu'}</span><h3>{doctor.name}</h3><p>{doctor.specialization}</p><span className="doctor-department">{doctor.department} <span>•</span> ₹{doctor.fee}</span></div><a className="button button-secondary button-full" href="#booking">Book with {doctor.name} <ArrowRight size={15} /></a></div>)}</div></div></section><BookingSection /><section className="queue-section"><div className="wrap queue-grid"><div><SectionHeading eyebrow="Stay in the loop" title="Your visit, at a glance." copy="Check your live queue position with your booking ID or phone number." /><div className="queue-trust"><span><ShieldCheck size={16} /> Private by design</span><span><Activity size={16} /> Updates every 30 sec</span></div></div><QueueTracker /></div></section><section id="about" className="section about-section"><div className="wrap about-grid reveal"><div className="reveal-left"><SectionHeading eyebrow="Find us in Vamanjoor" title="Care that feels close to home." copy="Aruna Healthcare brings thoughtful primary and specialist care to families across Mangaluru." /><div className="address-block"><MapPin size={20} /><div><strong>Sadhana Sahakari Soudha</strong><span>Vamanjoor, Mangaluru — 575028</span></div></div><div className="contact-row"><a href="tel:+918242222202"><Phone size={16} /> +91 824 222 2202</a><a href="https://wa.me/918242222202" target="_blank" rel="noreferrer"><MessageCircle size={16} /> WhatsApp</a></div></div><div className="about-card reveal-right"><div className="about-card-top"><span className="eyebrow">Open 6 days</span><span className="mini-pill"><CircleDot size={10} /> {availableMedicines} pharmacy essentials in stock</span></div><div className="hours-row"><span>Monday – Saturday</span><strong>8:00 AM — 8:00 PM</strong></div><div className="hours-row"><span>Sunday</span><strong className="muted">Closed</strong></div><div className="map-illustration"><div className="map-road road-one" /><div className="map-road road-two" /><div className="map-pin"><MapPin size={24} /></div><span className="map-label">Aruna Healthcare</span></div></div></div></section></main><footer className="public-footer reveal"><div className="wrap footer-grid"><BrandMark /><p>Clear care. Close to home. Built for Vamanjoor.</p><div className="footer-actions"><Link to="/admin">Admin portal <ArrowUpRight size={14} /></Link><span>© 2026 Aruna Healthcare</span></div></div></footer></div>; }

