        <div className="apollo-specialty-tabs reveal" role="tablist" aria-label="Care specialties">{care.map((item, index) => <button key={item.name} type="button" role="tab" aria-selected={activeCare === index} className={activeCare === index ? 'active' : ''} onClick={() => setActiveCare(index)}>{item.name}</button>)}</div>
